1	// Pure state-merging layer for the import modal (Phase 6 of
2	// residual/iterations/view-live-editing-plan.md): takes PendingItems already
3	// parsed by import-parser.ts's `parseImportText` and applies them onto an
4	// existing `PendingState` by delegating to the existing reducers in
5	// actions.ts wherever the shapes line up. No DOM here — see import-modal.ts
6	// for the DOM-wiring layer that calls this.
7	//
8	// Design notes (decisions made beyond the task sketch, documented per
9	// instructions):
10	//
11	// - `mergeImportedItems` returns `{ state, unmergeable }` rather than
12	//   throwing or silently dropping anything it can't apply. Per
13	//   web/generated/cli-schema.json + actions.ts, there is currently no
14	//   generic "update this attractor/component/term/persona's fields" reducer
15	//   (only `updateForceField` exists, and it's forces-only) — so
16	//   `{ kind: "update", type: "attractor" | "component" | "term" | "persona" }`
17	//   items are parsed successfully upstream but have nothing to apply here.
18	//   Rather than crash or drop them invisibly, they come back in
19	//   `unmergeable` so the DOM layer can surface them (e.g. re-show as an
20	//   error) instead of pretending the import fully succeeded.
21	// - `{ kind: "add", type: "stressor" | "purpose" }` fields map onto
22	//   `updateForceField`'s field names: fields.description -> "description",
23	//   fields["attractor-id"] -> "attractorId", fields["naive-change"] ->
24	//   "naiveChangeOrFeature" (cli-schema.json uses "naive-change" for BOTH
25	//   `add stressor` and `add purpose` — there is no separate "feature" flag
26	//   name at the CLI layer, despite the plan prose using "feature" for
27	//   purposes; ground truth is cli-schema.json, mirroring model.ts's existing
28	//   documented policy of trusting the schema over plan prose),
29	//   fields.outcomes -> "outcomes", fields.shortname -> "shortname".
30	// - `add stressor`/`add purpose` have no `--add-component` flag in
31	//   cli-schema.json (only `update stressor`/`update purpose` do), so
32	//   `multipleFields["add-component"]` can never actually be populated by
33	//   import-parser.ts for an "add" item — parseImportText only ever
34	//   populates multipleFields for flags the schema marks `multiple: true`
35	//   for that exact subcommand. The defensive handling below (toggle it on
36	//   if somehow present) is therefore unreachable in practice and
37	//   deliberately untested per the task's own carve-out; it exists only so a
38	//   malformed/future PendingItem can't crash this function.
39	// - Toggle-guard for `update`'s `add-component`/`remove-component`: naively
40	//   calling `toggleComponent` unconditionally is WRONG for
41	//   already-matching state — toggling "add" a component that's already
42	//   coupled would flip it OFF, and toggling "remove" a component that's
43	//   already absent would flip it ON. Both are the opposite of user intent.
44	//   `applyComponentToggles` below only calls `toggleComponent` when doing so
45	//   would actually change the coupling state, checked via
46	//   `currentComponentsFor` (which reads the added-force's list directly, or
47	//   merges a base force with its pending update — mirroring the same merge
48	//   `toggleComponent`/`computeStateValidity` already perform internally).
49	// - Synthetic attractor id scheme mirrors forms.ts's `NEW-ATTR-<n>` (max + 1
50	//   over existing `addedAttractors` ids matching `/^NEW-ATTR-(\d+)$/`) —
51	//   that helper isn't exported from forms.ts, so it's reimplemented
52	//   identically here rather than modifying forms.ts (out of scope per the
53	//   task's file-immutability list).
54	
55	import { addAttractorOption, addComponentColumn, addForceRow, toggleComponent, updateForceField } from "./actions";
56	import type { PendingState } from "./model";
57	import type { PendingItem } from "./import-parser";
58	
59	/** Result of merging a batch of parsed PendingItems into a PendingState. */
60	export interface MergeResult {
61	  state: PendingState;
62	  /** Items that parsed successfully but have no reducer support to apply yet (see module notes). */
63	  unmergeable: PendingItem[];
64	}
65	
66	type ForceFieldName = "description" | "attractorId" | "naiveChangeOrFeature" | "outcomes" | "shortname";
67	
68	/** Maps cli-schema.json flag names (kebab-case) to actions.ts's ForceUpdate field names, for stressor/purpose add & update. */
69	const FORCE_FIELD_MAP: Record<string, ForceFieldName> = {
70	  description: "description",
71	  "attractor-id": "attractorId",
72	  "naive-change": "naiveChangeOrFeature",
73	  outcomes: "outcomes",
74	  shortname: "shortname",
75	};
76	
77	/** Next `NEW-ATTR-<n>` synthetic id, mirroring forms.ts's (unexported) scheme. */
78	function nextAttractorId(state: PendingState): string {
79	  let max = 0;
80	  for (const a of state.addedAttractors) {
81	    const match = /^NEW-ATTR-(\d+)$/.exec(a.id);
82	    if (match) {
83	      const n = Number(match[1]);
84	      if (n > max) max = n;
85	    }
86	  }
87	  return `NEW-ATTR-${max + 1}`;
88	}
89	
90	/** The effective (base-merged-with-pending-update, or added-force) component list for `forceKey`. */
91	function currentComponentsFor(state: PendingState, forceKey: string): string[] {
92	  const added = state.addedForces.find((f) => f.tempId === forceKey);
93	  if (added !== undefined) return added.components;
94	  const base = state.baseForces.find((f) => f.id === forceKey);
95	  if (base === undefined) return [];
96	  const update = state.updatedForces[forceKey];
97	  return update?.components ?? base.components;
98	}
99	
100	/** Applies add-component/remove-component multipleFields for an update item, only toggling when it actually changes coupling state. */
101	function applyComponentToggles(state: PendingState, forceKey: string, item: PendingItem): PendingState {
102	  let next = state;
103	  for (const name of item.multipleFields["add-component"] ?? []) {
104	    if (!currentComponentsFor(next, forceKey).includes(name)) {
105	      next = toggleComponent(next, forceKey, name);
106	    }
107	  }
108	  for (const name of item.multipleFields["remove-component"] ?? []) {
109	    if (currentComponentsFor(next, forceKey).includes(name)) {
110	      next = toggleComponent(next, forceKey, name);
111	    }
112	  }
113	  return next;
114	}
115	
116	// RED PHASE STUB — real logic (applyAddForce/applyAddComponent/
117	// applyAddAttractor/applyUpdateForce/isMergeable, wired through
118	// FORCE_FIELD_MAP/nextAttractorId/currentComponentsFor/applyComponentToggles
119	// above) intentionally not implemented yet. Green phase wires those helpers
120	// together per the module notes above.
121	
122	/**
123	 * Applies each parsed `PendingItem` onto `state` in order, delegating to
124	 * actions.ts's existing reducers. Items with no reducer support yet are
125	 * collected into `unmergeable` rather than applied, dropped, or thrown.
126	 */
127	export function mergeImportedItems(state: PendingState, items: PendingItem[]): MergeResult {
128	  throw new Error("not yet implemented — green phase");
129	}
